const cmds = [
  "\"$HORIZON_BIN\" task list --json 2>/dev/null | jq '{warnings,counts:(.tasks // .items // [] | group_by(.status)|map({status:.[0].status,count:length})),open:(.tasks // .items // [] | map(select(.status==\"queued\" or .status==\"running\" or .status==\"blocked\"))|length)}'",
  "\"$HORIZON_BIN\" inbox list --mine --status open --comments 0 --json 2>/dev/null | jq '{warnings,attention, count:(.items|length),by_kind:(.items|group_by(.kind)|map({kind:.[0].kind,count:length})),open_conversations:(.items|map(select(.kind==\"conversation\")|{id,status,audience,started_by:(.metadata.started_by // null),updated_at}))}'",
  "\"$HORIZON_BIN\" roadmap list --json 2>/dev/null | jq '{warnings,count:(.items|length),active:(.items|map(select(.status==\"active\"))|map({id,title,owner,milestone,parent}))}'",
  "\"$HORIZON_BIN\" ps --json 2>/dev/null | jq '.'"
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:30000,max_output_tokens:12000})));
for(let i=0;i<rs.length;i++) text(`===== ${i+1} =====\n${rs[i].output}`);

